sketches.source:
setcpm(54/3)

// One cycle is a bar of 3/4; the long second beat is the sarabande's lean
// Dm, Bb, Gm, A, Dm, Bb, A7, Dm
const harpsichord = (x) => x.s("square").pw(.15)
  .attack(.002).decay(.4).sustain(0).release(.2).lpf(3200).room(.4)

right: note("<[a4 d5@2] [f5 d5@2] [bb4 g4@2] [c#5@3] [e5 f5@2] [d5 bb4@2] [g4 e4@2] [d4@3]>")
  .harpsichord().gain(.18)
left: note("<d3 bb2 g2 a2 d3 bb2 a2 d2>").harpsichord().gain(.16)

// The strings step through the interaural phase, two bars at a time
// 0 degrees: centred. 90: looser. 180: diffuse and all around, and nearly gone in mono
pad: note("<[d3,f3,a3] [bb2,d3,f3] [g2,bb2,d3] [a2,c#3,e3] [d3,f3,a3] [bb2,d3,f3] [a2,c#3,g3] [d3,f3,a3]>")
  .s("sawtooth").unison(2).detune(.1).iphase("<0 0 90 90 180 180 90 90>")
  .lpf(1000).attack(1).sustain(1).release(2).gain(.1)

setcpm(50/4)

// earsh raises the right ear and lowers the left by half the value each
// The strings breathe out and back in: 3, 8, 15, then 8 cents, two bars each
strings: note("<[g2,d3,b3,d4] [e2,b2,g3,b3] [c3,g3,e4] [d3,a3,f#4]>").slow(2)
  .s("sawtooth").unison(2).detune(.1).earsh("<3 3 8 8 15 15 8 8>")
  .lpf(1200).attack(2).sustain(1).release(3).room(.7).size(.9).gain(.12)

// The piano sings in the centre, the same in both ears: G, Em, C, D7
piano: note("<[b4@3 a4] [g4@4] [g4@2 b4 e5] [d5@4] [e5@3 d5] [c5@2 e4@2] [f#4@2 a4 d5] [c5@2 a4@2]>")
  .s("triangle").timbre("soft").attack(.005).decay(1.6).sustain(.1).release(1.6)
  .room(.6).size(.8).gain(.26)

// The cello holds the roots
cello: note("<g1 e2 c2 d2>").slow(2).s("sawtooth").vib(4.5).vibdepth(.08)
  .lpf(600).attack(1).sustain(.8).release(2).room(.5).gain(.18)

setcpm(56/4)

// irate turns the phase between the ears, in turns per second, like a very slow rotating speaker
// All rates stay below 3 Hz, so no pulse warning is needed: Eb, Cm, Ab, Bb
organ: note("<[eb3,g3,bb3] [c3,eb3,g3] [ab2,c3,eb3] [bb2,d3,f3]>")
  .s("sawtooth").timbre("organ").irate("<.2 .4 .8 .4>")
  .lpf(1200).attack(.5).sustain(.9).release(1).space("church").gain(.14)

// The flute, the same in both ears
flute: note("<[g4@3 bb4] [c5@2 bb4 g4] [ab4@3 c5] [bb4@4] [eb5@3 d5] [c5@2 g4@2] [c5 bb4 ab4 c5] [bb4@2 d4@2]>")
  .s("sine").timbre("hollow").vib(5).vibdepth(.1)
  .attack(.08).sustain(.7).release(.6).room(.5).gain(.22)

// The pedal walks the roots, centred
pedal: note("<eb2 c2 ab1 bb1>").s("sawtooth").timbre("organ").lpf(450)
  .attack(.3).sustain(.8).release(1).space("church").gain(.2)

setcpm(80/4)

// A low-pass on each ear alone, sweeping in opposite directions every eight bars
// The level stays put; only the brightness wanders: Em, C, Am, B
etude: n("0 2 4 2 7 4 2 4").add("<0 -2 -4 -3>").scale("E:minor").transpose(12)
  .s("triangle").timbre("bright")
  .lcutoff(saw.range(600, 4000).slow(8)).rcutoff(isaw.range(600, 4000).slow(8))
  .attack(.003).decay(.4).sustain(.1).release(.4).room(.4).gain(.22)

// A high-pass on the right ear only: the inner voices sound fuller on the left
inner: note("<[g3,b3] [g3,c4] [a3,c4] [f#3,b3]>").s("sawtooth").rhcutoff(1100)
  .lpf(1600).attack(.6).sustain(.8).release(1).room(.4).gain(.1)

// The left hand on the roots, the same in both ears
left: note("<e2 c2 a1 b1>").s("triangle").timbre("soft")
  .attack(.005).decay(1.2).sustain(.2).release(1).gain(.24)

setcpm(60/3)

// One cycle is a bar of 3/4
// A 2 Hz binaural drone on an open fifth: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("[bb1,f2]").slow(8).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.22)

// The harp minuet, floating a little above your head: Bb, Bb, Cm, F, Bb, Eb, F, Bb
harp: note("<[d5 c5 bb4] [f4@2 bb4] [c5 eb5 d5] [c5@3] [d5 f5 eb5] [d5@2 bb4] [c5 a4 c5] [bb4@3]>")
  .s("triangle").timbre("soft").attack(.002).decay(1.4).sustain(0).release(1.4)
  .elevation(30).distance(2).room(.6).size(.85).gain(.22)

// A soft root on each downbeat
bass: note("<bb1 bb1 c2 f1 bb1 eb2 f1 bb1>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.18)

// Crickets far away
crickets: s("insect").slow(4).distance(8).gain(.05)
